// Package index builds the deterministic structural slice of the understand
// graph: directories, files, and (for Go) symbols.
//
// Per the spec the POC ships full symbol extraction for Go via stdlib
// `go/parser` + `go/token` only. All other languages get file-level nodes.
// Tree-sitter and per-language plugins are intentionally deferred so the
// graph schema stays shape-stable for follow-up work.
package index

import (
	"context"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/understand/graph"
)

// excludedDirs are directory names that scanning never descends into.
// Order matters only for readability; lookups use the map below.
var excludedDirs = map[string]struct{}{
	".git":         {},
	".entire":      {},
	".marvin":      {},
	"node_modules": {},
	"vendor":       {},
	".vscode":      {},
	".idea":        {},
}

// languageByExt is the file extension → language label map. The label is the
// `Language` field on file nodes; structural code only special-cases "go" but
// we keep a few well-known labels so semantic stages and the dashboard can
// group files sensibly.
var languageByExt = map[string]string{
	".go":      "go",
	".py":      "python",
	".ts":      "typescript",
	".tsx":     "typescript",
	".js":      "javascript",
	".jsx":     "javascript",
	".rs":      "rust",
	".rb":      "ruby",
	".java":    "java",
	".kt":      "kotlin",
	".swift":   "swift",
	".c":       "c",
	".cc":      "cpp",
	".cpp":     "cpp",
	".h":       "c",
	".hpp":     "cpp",
	".cs":      "csharp",
	".sh":      "shell",
	".bash":    "shell",
	".md":      "markdown",
	".json":    "json",
	".yaml":    "yaml",
	".yml":     "yaml",
	".toml":    "toml",
	".html":    "html",
	".css":     "css",
	".sql":     "sql",
	".proto":   "proto",
	".graphql": "graphql",
}

// ScanResult is the outcome of a structural index pass.
type ScanResult struct {
	// Slice is the structural graph slice (nodes + edges).
	Slice *graph.Slice
	// Languages is the sorted, deduplicated list of languages observed.
	Languages []string
	// FileCount is the number of file nodes emitted (handy for manifests).
	FileCount int
	// SymbolCount is the number of symbol nodes emitted (Go-only for the POC).
	SymbolCount int
}

// Scan walks repoRoot, builds directory/file/symbol nodes, and links them
// with `contains` edges. Errors are returned only for I/O failures that prevent
// the scan from completing; per-file parse errors are silently downgraded to
// "no symbols" so a malformed source file does not break the whole index.
func Scan(ctx context.Context, repoRoot string) (*ScanResult, error) {
	if repoRoot == "" {
		return nil, fmt.Errorf("scan: empty repoRoot")
	}
	st, err := os.Stat(repoRoot)
	if err != nil {
		return nil, fmt.Errorf("scan: stat repo root: %w", err)
	}
	if !st.IsDir() {
		return nil, fmt.Errorf("scan: repo root %q is not a directory", repoRoot)
	}

	slice := &graph.Slice{}
	repoNodeID := "repo:."
	slice.Nodes = append(slice.Nodes, graph.Node{
		ID:   repoNodeID,
		Type: graph.NodeRepo,
		Name: filepath.Base(repoRoot),
	})

	dirNodes := map[string]string{".": repoNodeID}
	languages := map[string]struct{}{}
	files := 0
	symbols := 0

	err = filepath.WalkDir(repoRoot, func(path string, d fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			// Skip unreadable subtrees rather than failing the whole index.
			if d != nil && d.IsDir() {
				return fs.SkipDir
			}
			return nil
		}
		if err := ctx.Err(); err != nil {
			return err
		}

		// Translate to forward-slash repo-relative.
		rel, err := filepath.Rel(repoRoot, path)
		if err != nil {
			return nil
		}
		rel = filepath.ToSlash(rel)
		if rel == "." {
			return nil
		}

		if d.IsDir() {
			if _, skip := excludedDirs[d.Name()]; skip {
				return fs.SkipDir
			}
			parentRel := filepath.ToSlash(filepath.Dir(rel))
			parentID, ok := dirNodes[parentRel]
			if !ok {
				parentID = repoNodeID
			}
			id := "dir:" + rel
			slice.Nodes = append(slice.Nodes, graph.Node{
				ID:   id,
				Type: graph.NodeDirectory,
				Name: d.Name(),
				Path: rel,
			})
			slice.Edges = append(slice.Edges, graph.Edge{
				ID:   "e:contains:" + parentID + "->" + id,
				From: parentID,
				To:   id,
				Type: graph.EdgeContains,
			})
			dirNodes[rel] = id
			return nil
		}

		// Skip files that begin with `.` at any path component.
		// Keeps `.gitignore` itself out of the index along with editor turds.
		if hasDotComponent(rel) {
			return nil
		}

		ext := strings.ToLower(filepath.Ext(rel))
		lang := languageByExt[ext]
		if lang != "" {
			languages[lang] = struct{}{}
		}

		fileID := "file:" + rel
		parentRel := filepath.ToSlash(filepath.Dir(rel))
		parentID, ok := dirNodes[parentRel]
		if !ok {
			parentID = repoNodeID
		}

		fileNode := graph.Node{
			ID:       fileID,
			Type:     graph.NodeFile,
			Name:     filepath.Base(rel),
			Path:     rel,
			Language: lang,
		}
		// Stat for size only; LineStart/End are reserved for symbol nodes.
		if info, errInfo := d.Info(); errInfo == nil {
			fileNode.Attrs = map[string]any{"size_bytes": info.Size()}
		}
		slice.Nodes = append(slice.Nodes, fileNode)
		slice.Edges = append(slice.Edges, graph.Edge{
			ID:   "e:contains:" + parentID + "->" + fileID,
			From: parentID,
			To:   fileID,
			Type: graph.EdgeContains,
		})
		files++

		if lang == "go" {
			added, errParse := extractGoSymbols(slice, rel, fileID, path)
			if errParse == nil {
				symbols += added
			}
			// Parse errors are intentionally swallowed: a malformed Go file
			// should not prevent the rest of the structural index from
			// landing. Symbol coverage for that file is simply absent.
		}
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("scan: walk: %w", err)
	}

	langs := make([]string, 0, len(languages))
	for l := range languages {
		langs = append(langs, l)
	}
	sort.Strings(langs)

	return &ScanResult{
		Slice:       slice,
		Languages:   langs,
		FileCount:   files,
		SymbolCount: symbols,
	}, nil
}

// hasDotComponent reports whether any path component begins with a dot.
// Forward-slash assumed (rel paths are normalized before this is called).
func hasDotComponent(rel string) bool {
	for _, p := range strings.Split(rel, "/") {
		if p == "" {
			continue
		}
		if strings.HasPrefix(p, ".") {
			return true
		}
	}
	return false
}

package index

import (
	"go/ast"
	"go/parser"
	"go/token"

	"github.com/entireio/cli/cmd/entire/cli/understand/graph"
)

// extractGoSymbols parses a single Go file and appends symbol nodes plus
// `contains` edges from the file node to each symbol. Returns the number of
// symbol nodes added.
//
// The POC ships function, method, type, struct, and interface symbols. Tests
// (Test*/Benchmark*/Fuzz*) are tagged as SymbolTest so hotspots and tour
// surfaces can hide them when desired.
func extractGoSymbols(slice *graph.Slice, relPath, fileID, absPath string) (int, error) {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, absPath, nil, parser.SkipObjectResolution|parser.ParseComments)
	if err != nil {
		return 0, err
	}

	added := 0
	for _, decl := range file.Decls {
		switch d := decl.(type) {
		case *ast.FuncDecl:
			added += emitFunc(slice, relPath, fileID, fset, d)
		case *ast.GenDecl:
			added += emitGenDecl(slice, relPath, fileID, fset, d)
		}
	}
	return added, nil
}

// emitFunc handles top-level function and method declarations.
func emitFunc(slice *graph.Slice, relPath, fileID string, fset *token.FileSet, fn *ast.FuncDecl) int {
	if fn.Name == nil || !fn.Name.IsExported() && !alwaysIndex(fn.Name.Name) {
		// Index unexported names too — they show up in tour/explain — but use
		// the exported guard to skip empty names defensively.
		if fn.Name == nil {
			return 0
		}
	}

	kind := graph.SymbolFunction
	idSuffix := fn.Name.Name
	if fn.Recv != nil && len(fn.Recv.List) > 0 {
		kind = graph.SymbolMethod
		recvType := receiverTypeName(fn.Recv.List[0].Type)
		if recvType != "" {
			idSuffix = recvType + "." + fn.Name.Name
		}
	}
	if isTestFunc(fn.Name.Name) {
		kind = graph.SymbolTest
	}

	startPos := fset.Position(fn.Pos())
	endPos := fset.Position(fn.End())

	id := "sym:" + relPath + ":" + idSuffix
	node := graph.Node{
		ID:         id,
		Type:       graph.NodeSymbol,
		SymbolKind: kind,
		Name:       idSuffix,
		Path:       relPath,
		Language:   "go",
		LineStart:  startPos.Line,
		LineEnd:    endPos.Line,
	}
	slice.Nodes = append(slice.Nodes, node)
	slice.Edges = append(slice.Edges, graph.Edge{
		ID:   "e:contains:" + fileID + "->" + id,
		From: fileID,
		To:   id,
		Type: graph.EdgeContains,
	})
	return 1
}

// emitGenDecl handles `type`, `var`, `const` blocks. The POC indexes types
// only (struct/interface/alias) — plain vars and consts add noise without
// pulling much weight in moments 1–8.
func emitGenDecl(slice *graph.Slice, relPath, fileID string, fset *token.FileSet, gd *ast.GenDecl) int {
	if gd.Tok != token.TYPE {
		return 0
	}
	added := 0
	for _, spec := range gd.Specs {
		ts, ok := spec.(*ast.TypeSpec)
		if !ok || ts.Name == nil {
			continue
		}
		kind := graph.SymbolType
		switch ts.Type.(type) {
		case *ast.StructType:
			kind = graph.SymbolStruct
		case *ast.InterfaceType:
			kind = graph.SymbolInterface
		}

		startPos := fset.Position(ts.Pos())
		endPos := fset.Position(ts.End())

		id := "sym:" + relPath + ":" + ts.Name.Name
		slice.Nodes = append(slice.Nodes, graph.Node{
			ID:         id,
			Type:       graph.NodeSymbol,
			SymbolKind: kind,
			Name:       ts.Name.Name,
			Path:       relPath,
			Language:   "go",
			LineStart:  startPos.Line,
			LineEnd:    endPos.Line,
		})
		slice.Edges = append(slice.Edges, graph.Edge{
			ID:   "e:contains:" + fileID + "->" + id,
			From: fileID,
			To:   id,
			Type: graph.EdgeContains,
		})
		added++
	}
	return added
}

// receiverTypeName returns the bare type name from a method receiver, stripping
// any `*` pointer wrapper. Returns "" when the AST is not the shapes we expect
// (very rare in real code).
func receiverTypeName(expr ast.Expr) string {
	switch t := expr.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.StarExpr:
		if id, ok := t.X.(*ast.Ident); ok {
			return id.Name
		}
	}
	return ""
}

func isTestFunc(name string) bool {
	switch {
	case len(name) > 4 && name[:4] == "Test":
		return true
	case len(name) > 9 && name[:9] == "Benchmark":
		return true
	case len(name) > 4 && name[:4] == "Fuzz":
		return true
	}
	return false
}

// alwaysIndex returns true for names that are not exported but should still be
// indexed (e.g. `init`, `main`). We currently always emit symbols regardless
// of export status, but keep this hook so we can tighten later.
func alwaysIndex(name string) bool {
	return name == "init" || name == "main"
}

package index

import (
	"context"
	"os"
	"path/filepath"
	"slices"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/understand/graph"
)

func TestScan_RepoNodeAndExclusions(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	writeFile(t, dir, "README.md", "# repo\n")
	writeFile(t, dir, "src/main.go", "package main\nfunc main() {}\n")
	writeFile(t, dir, ".git/config", "[core]\n")             // must not appear
	writeFile(t, dir, ".entire/cache/x.json", "{}")          // must not appear
	writeFile(t, dir, "node_modules/foo/index.js", "x = 1;") // must not appear
	writeFile(t, dir, "vendor/lib/x.go", "package lib\n")    // must not appear

	res, err := Scan(context.Background(), dir)
	if err != nil {
		t.Fatalf("Scan: %v", err)
	}

	wantPaths := []string{"README.md", "src/main.go"}
	gotPaths := filePaths(res.Slice)
	if !slices.Equal(gotPaths, wantPaths) {
		t.Errorf("file paths = %v; want %v", gotPaths, wantPaths)
	}

	// Repo node always present.
	if !hasNodeID(res.Slice, "repo:.") {
		t.Errorf("repo node missing")
	}
}

func TestScan_GoSymbols(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	src := `package svc

// User is a record.
type User struct {
	ID string
}

type Repo interface {
	Find(id string) (*User, error)
}

func NewUser(id string) *User { return &User{ID: id} }

func (u *User) Greet() string { return "hi " + u.ID }

func TestUser(t *struct{}) {} // intentionally not a real test signature
`
	writeFile(t, dir, "svc/user.go", src)

	res, err := Scan(context.Background(), dir)
	if err != nil {
		t.Fatalf("Scan: %v", err)
	}

	wantSymbols := map[string]graph.SymbolKind{
		"User":       graph.SymbolStruct,
		"Repo":       graph.SymbolInterface,
		"NewUser":    graph.SymbolFunction,
		"User.Greet": graph.SymbolMethod,
		"TestUser":   graph.SymbolTest,
	}

	for _, n := range res.Slice.Nodes {
		if n.Type != graph.NodeSymbol {
			continue
		}
		want, ok := wantSymbols[n.Name]
		if !ok {
			continue
		}
		if n.SymbolKind != want {
			t.Errorf("symbol %q kind = %q; want %q", n.Name, n.SymbolKind, want)
		}
		if n.Path != "svc/user.go" {
			t.Errorf("symbol %q path = %q; want svc/user.go", n.Name, n.Path)
		}
		if n.LineStart == 0 || n.LineEnd == 0 {
			t.Errorf("symbol %q missing line range: start=%d end=%d", n.Name, n.LineStart, n.LineEnd)
		}
		delete(wantSymbols, n.Name)
	}
	if len(wantSymbols) > 0 {
		t.Errorf("missing expected symbols: %v", wantSymbols)
	}
	if res.SymbolCount < 5 {
		t.Errorf("SymbolCount = %d; want >= 5", res.SymbolCount)
	}
}

func TestScan_FileLevelOnlyForOtherLanguages(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	writeFile(t, dir, "app.py", "def hello():\n    return 1\n")
	writeFile(t, dir, "ui.tsx", "export const X = () => null\n")

	res, err := Scan(context.Background(), dir)
	if err != nil {
		t.Fatalf("Scan: %v", err)
	}

	for _, n := range res.Slice.Nodes {
		if n.Type == graph.NodeSymbol {
			t.Errorf("unexpected symbol node for non-Go file: %+v", n)
		}
	}

	// Languages list should be sorted + deduped.
	wantLangs := []string{"python", "typescript"}
	if !slices.Equal(res.Languages, wantLangs) {
		t.Errorf("Languages = %v; want %v", res.Languages, wantLangs)
	}
}

func TestScan_MalformedGoFileDoesNotAbort(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	writeFile(t, dir, "ok.go", "package main\nfunc main() {}\n")
	writeFile(t, dir, "broken.go", "package main\n}}}}\nfunc but-wait!\n")

	res, err := Scan(context.Background(), dir)
	if err != nil {
		t.Fatalf("Scan: %v", err)
	}
	// Both files appear as nodes.
	gotPaths := filePaths(res.Slice)
	if !slices.Equal(gotPaths, []string{"broken.go", "ok.go"}) {
		t.Errorf("file paths = %v; want sorted", gotPaths)
	}
	// At least the `main` symbol from ok.go survived.
	mainSeen := false
	for _, n := range res.Slice.Nodes {
		if n.Type == graph.NodeSymbol && n.Name == "main" && n.Path == "ok.go" {
			mainSeen = true
		}
	}
	if !mainSeen {
		t.Errorf("expected `main` symbol from ok.go")
	}
}

func TestScan_DirectoryNodesAndContainsEdges(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	writeFile(t, dir, "a/b/c.go", "package c\nfunc Hello() {}\n")

	res, err := Scan(context.Background(), dir)
	if err != nil {
		t.Fatalf("Scan: %v", err)
	}

	wantDirIDs := []string{"dir:a", "dir:a/b"}
	for _, want := range wantDirIDs {
		if !hasNodeID(res.Slice, want) {
			t.Errorf("missing dir node %q", want)
		}
	}

	// repo:. → dir:a, dir:a → dir:a/b, dir:a/b → file:a/b/c.go, file → sym
	wantEdges := []struct{ from, to string }{
		{"repo:.", "dir:a"},
		{"dir:a", "dir:a/b"},
		{"dir:a/b", "file:a/b/c.go"},
		{"file:a/b/c.go", "sym:a/b/c.go:Hello"},
	}
	for _, want := range wantEdges {
		if !hasContainsEdge(res.Slice, want.from, want.to) {
			t.Errorf("missing contains edge %s -> %s", want.from, want.to)
		}
	}
}

func writeFile(t *testing.T, dir, rel, content string) {
	t.Helper()
	full := filepath.Join(dir, filepath.FromSlash(rel))
	if err := os.MkdirAll(filepath.Dir(full), 0o750); err != nil {
		t.Fatalf("MkdirAll: %v", err)
	}
	if err := os.WriteFile(full, []byte(content), 0o600); err != nil {
		t.Fatalf("WriteFile %s: %v", rel, err)
	}
}

func filePaths(s *graph.Slice) []string {
	paths := []string{}
	for _, n := range s.Nodes {
		if n.Type == graph.NodeFile {
			paths = append(paths, n.Path)
		}
	}
	slices.Sort(paths)
	return paths
}

func hasNodeID(s *graph.Slice, id string) bool {
	for _, n := range s.Nodes {
		if n.ID == id {
			return true
		}
	}
	return false
}

func hasContainsEdge(s *graph.Slice, from, to string) bool {
	for _, e := range s.Edges {
		if e.Type == graph.EdgeContains && e.From == from && e.To == to {
			return true
		}
	}
	return false
}

